() => {
  const de = document.documentElement;
  const b = document.body;
  const totalH = Math.max(de.scrollHeight, b.scrollHeight);
  // Fonts used
  const fontSet = new Set();
  document.querySelectorAll('h1,h2,h3,h4,h5,h6,p,span,a,div').forEach(el=>{
    const cs = getComputedStyle(el);
    if(el.textContent && el.textContent.trim().length) fontSet.add(cs.fontFamily);
  });
  // Body bg
  const bodyBg = getComputedStyle(b).backgroundColor;
  const htmlBg = getComputedStyle(de).backgroundColor;
  // heading sample
  const h1 = document.querySelector('h1');
  const h1cs = h1?getComputedStyle(h1):null;
  return {
    totalH, vw: window.innerWidth, vh: window.innerHeight,
    bodyBg, htmlBg,
    fonts: [...fontSet].slice(0,15),
    h1sample: h1cs?{family:h1cs.fontFamily, weight:h1cs.fontWeight, size:h1cs.fontSize, color:h1cs.color, letterSpacing:h1cs.letterSpacing, lineHeight:h1cs.lineHeight, text:h1.textContent.slice(0,40)}:null,
  };
}

() => {
  // Find elements with notable background colors by scanning
  const colors = {};
  document.querySelectorAll('*').forEach(el=>{
    const cs = getComputedStyle(el);
    const bg = cs.backgroundColor;
    if(bg && bg!=='rgba(0, 0, 0, 0)' && bg!=='rgb(255, 255, 255)'){
      const r = el.getBoundingClientRect();
      if(r.width>200 && r.height>100){
        colors[bg] = (colors[bg]||0)+1;
      }
    }
  });
  // sort
  const sorted = Object.entries(colors).sort((a,b)=>b[1]-a[1]).slice(0,12);
  // Also grab specific known accent - the orange nav
  return { bigBgColors: sorted };
}

