() => {
  window.scrollTo(0,0);
  // grab hero image layout details
  const imgs = [...document.querySelectorAll('img')].filter(im=>{
    const r = im.getBoundingClientRect();
    return r.width>100 && r.top<900 && r.bottom>0;
  }).map(im=>{
    const r=im.getBoundingClientRect();
    return {src: im.currentSrc||im.src, x:Math.round(r.x), y:Math.round(r.y), w:Math.round(r.width), h:Math.round(r.height)};
  });
  return {heroImgs: imgs.slice(0,10)};
}

() => {
  const imgs = [...document.querySelectorAll('img')].filter(im=>(im.currentSrc||im.src).includes('framerusercontent')).map(im=>{
    const r=im.getBoundingClientRect();
    return {src:(im.currentSrc||im.src).split('?')[0].split('/').pop(), x:Math.round(r.x), y:Math.round(r.y), w:Math.round(r.width), h:Math.round(r.height)};
  }).filter(o=>o.w>50);
  return {heroCollage: imgs};
}

() => {
  const fonts = [];
  for(const sh of document.styleSheets){
    let rules; try{rules=sh.cssRules}catch(e){continue}
    if(!rules) continue;
    for(const r of rules){
      if(r.type===5 && r.cssText.includes('Beausite')){
        const m = r.cssText.match(/src:\s*url\(([^)]+)\)/);
        const fam = r.cssText.match(/font-family:\s*([^;]+);/);
        const wt = r.cssText.match(/font-weight:\s*([^;]+);/);
        fonts.push({fam:fam&&fam[1], weight:wt&&wt[1], url:m&&m[1]});
      }
    }
  }
  // Also grab case study portrait/poster imgs (grayscale) - look at videos/posters
  const vids = [...document.querySelectorAll('video')].map(v=>({poster:v.poster, src:v.currentSrc||v.querySelector('source')?.src}));
  return {beausite: fonts.slice(0,8), videos: vids.slice(0,8)};
}

