() => {
  window.scrollTo(0, 7800);
  return new Promise(res=>{
    setTimeout(()=>{
      // case study cards - find bg images or posters in that region
      const cards=[];
      document.querySelectorAll('video, img').forEach(el=>{
        const r=el.getBoundingClientRect();
        if(r.top>-200 && r.top<1400 && r.width>200 && r.height>200){
          cards.push({tag:el.tagName, src:(el.currentSrc||el.src||el.poster||'').slice(0,90), w:Math.round(r.width),h:Math.round(r.height),x:Math.round(r.x)});
        }
      });
      res({cards});
    }, 600);
  });
}

