          const src=media?(media.currentSrc||media.src||media.poster||(media.querySelector&&media.querySelector('source')&&media.querySelector('source').src)||''):'';
          const lines=card.innerText.split('\n').map(s=>s.trim()).filter(Boolean);
          const name=lines.find(l=>['Stripe','Sierra','Anthropic','Notion','Framer','Linear','Shopify'].includes(l));
          if(name) map.push({name, tag:media&&media.tagName, src:src.split('/').pop()});
        }
      });
      const seen={};const out=[];map.forEach(m=>{if(!seen[m.name]){seen[m.name]=1;out.push(m);}});
