    const pageY=Math.round(r.top+window.scrollY);
    const s=(v.currentSrc||(v.querySelector('source')&&v.querySelector('source').src)||'');
    out.push({file:s.split('/assets/')[1]||s.split('/').pop(), pageY, w:Math.round(r.width),h:Math.round(r.height),left:Math.round(r.left)});
  });
  // sort by pageY
  out.sort((a,b)=>a.pageY-b.pageY);
  return out;
}

() => {
  return new Promise(res=>{
    window.scrollTo(0,7600);
