      // sample the three visible card media at their centers (~y 450 in viewport)
      const pts=[[245,450],[720,450],[1195,450]];
      const found=pts.map(p=>{
        const el=document.elementFromPoint(p[0],p[1]);
        let node=el, chain=[];
        for(let i=0;i<4&&node;i++){
          const cs=getComputedStyle(node);
          const s=node.currentSrc||node.src||node.poster||'';
          chain.push({tag:node.tagName, src:(s||'').split('/').pop().slice(0,50), bg:cs.backgroundImage.slice(0,60)});
          node=node.parentElement;
