() => {
  return new Promise(res=>{
    window.scrollTo(0,8000);
    setTimeout(()=>{
      // Find the carousel container and read ALL card media including posters + lazy sources
      const cards=[];
      document.querySelectorAll('video').forEach(v=>{
        const r=v.getBoundingClientRect();
        const pageY=Math.round(r.top+window.scrollY);
        if(pageY<7700||pageY>8600)return; // carousel band
        cards.push({
          poster:(v.poster||'').split('/').pop(),
          src:(v.currentSrc||(v.querySelector('source')&&v.querySelector('source').src)||'').split('/assets/')[1]||'',
          left:Math.round(r.left), w:Math.round(r.width)
        });
      });
      // also read data-src / lazy attributes on card imgs
      const posters=[];
      document.querySelectorAll('img').forEach(im=>{
        const r=im.getBoundingClientRect();
        const pageY=Math.round(r.top+window.scrollY);
        if(pageY>7700&&pageY<8600&&r.width>200){
          posters.push({src:(im.currentSrc||im.src).split('/').pop().slice(0,40), left:Math.round(r.left)});
        }
      });
      res({cardVideos:cards, cardImgs:posters});
    },1200);
  });
}

() => {
  return new Promise(res=>{
    window.scrollTo(0,7900);
    setTimeout(()=>{
      // find horizontal scroller in carousel and scroll it fully right to trigger lazy loads
      let scroller=null;
      document.querySelectorAll('*').forEach(el=>{
        if(el.scrollWidth>el.clientWidth+300 && el.clientHeight>300 && el.clientHeight<900){
          const r=el.getBoundingClientRect();
          if(r.top+window.scrollY>7500&&r.top+window.scrollY<8700) scroller=el;
        }
      });
      if(scroller){
        scroller.scrollLeft = scroller.scrollWidth;
      }
      setTimeout(()=>res({scrolled: !!scroller, sw: scroller?scroller.scrollWidth:0}),1500);
    },500);
  });
}

() => {
  return new Promise(res=>{
    window.scrollTo(0,7900);
    setTimeout(()=>{
      // Read every video's poster + source across the whole doc, tagged by size class
      const all=[...document.querySelectorAll('video')].map(v=>{
        const src=(v.currentSrc||(v.querySelector('source')&&v.querySelector('source').src)||'');
        return {
          file: src.split('/assets/')[1]||src.split('/').pop(),
          poster:(v.poster||'').split('/images/')[1]?.split('?')[0]||'',
          vw:v.videoWidth, vh:v.videoHeight
        };
      });
      // unique by file
      const seen={};const uniq=[];all.forEach(a=>{if(a.file&&!seen[a.file]){seen[a.file]=1;uniq.push(a);}});
      res({videos:uniq});
    },1000);
  });
}

() => {
  return new Promise(res=>{
    window.scrollTo(0,7900);
    setTimeout(()=>{
      // Find carousel track (the horizontal scroller), iterate its direct card children
      let track=null;
      document.querySelectorAll('*').forEach(el=>{
        if(el.scrollWidth>el.clientWidth+300 && el.clientHeight>300 && el.clientHeight<820){
          const y=el.getBoundingClientRect().top+window.scrollY;
          if(y>7500&&y<8700) track=el;
        }
      });
      if(!track){res({err:'no track'});return;}
      const cards=[...track.children].map(card=>{
        const v=card.querySelector('video');
        const name=[...card.querySelectorAll('*')].map(e=>e.children.length===0&&e.textContent.trim()).find(t=>['Stripe','Sierra','Anthropic','Notion','Framer','Linear','Shopify'].includes(t));
        const src=v?(v.currentSrc||(v.querySelector('source')&&v.querySelector('source').src)||''):'';
        return {name, vid:src.split('/assets/')[1]||'', poster:(v&&v.poster||'').split('/images/')[1]?.split('?')[0]||''};
      });
      res({cards});
    },1200);
  });
}

