() => {
  // simulate mouse movement and confirm canvas exists + is drawing
  const c=document.getElementById('trail');
  const evt=(x,y)=>window.dispatchEvent(new MouseEvent('mousemove',{clientX:x,clientY:y}));
  for(let i=0;i<10;i++) evt(200+i*40, 300+i*20);
  return new Promise(res=>setTimeout(()=>{
    // sample canvas pixels for non-transparent
    const ctx=c.getContext('2d');
    const w=c.width, h=c.height;
    const data=ctx.getImageData(0,0,Math.min(w,600),Math.min(h,600)).data;
    let nonEmpty=0;
    for(let i=3;i<data.length;i+=4){ if(data[i]>0){nonEmpty++;} }
    return res({canvasW:w, canvasH:h, nonTransparentPixels:nonEmpty});
  },200));
}

